fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create first matrix: each row is a copy of x
    let mut matrix_x = Vec::with_capacity(rows);
    for _ in 0..rows {
        matrix_x.push(x.clone());
    }
    
    // Create second matrix: each row has the same y value in all columns
    let mut matrix_y = Vec::with_capacity(rows);
    for i in 0..rows {
        let row = vec![y[i]; cols];
        matrix_y.push(row);
    }
    
    (matrix_x, matrix_y)
}